function connectRequirements(req){if(!req)return '';const bits=[];if(req.disabled_reason)bits.push('Disabled reason: '+esc(req.disabled_reason));if(req.past_due&&req.past_due.length)bits.push('Past due: '+req.past_due.map(esc).join(', '));if(req.currently_due&&req.currently_due.length)bits.push('Currently due: '+req.currently_due.map(esc).join(', '));return bits.length?`<p class="muted">${bits.join('<br>')}</p>`:'';}
