const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const accentInk=hex=>{const rgb=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#000000':'#ffffff';};
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:n%100?2:0}).format(n/100).replace(/ |\u202f/g,'\u00a0');
let instalmentsApi=null;
function getInstalmentsApi(){if(!instalmentsApi&&window.createInstalmentsApi)instalmentsApi=window.createInstalmentsApi({mode:window.Instalments?window.Instalments.instalmentsModeFromLocation():'live',request:(path,opts)=>api(path,opts),paymentMode:config&&config.payment_mode});return instalmentsApi;}
function instalmentError(err){return (window.Instalments&&window.Instalments.friendlyError(err))||err?.message||'Something went wrong.';}
function promptSignIn(err){if(err&&(err.code==='UNAUTHENTICATED'||err.code==='AUTH_REQUIRED'||err.status===401)){authReturnPath=location.pathname;authModal('login','return');return true;}return false;}
function followCheckoutUrl(url){return window.Instalments&&window.Instalments.followCheckoutUrl?window.Instalments.followCheckoutUrl(url):(url&&url.startsWith('/')?'in-app':'redirect');}
