function showPaymentOptionErrors(form,err){form.querySelectorAll('.payment-options .field-error').forEach(el=>el.remove());const box=form.querySelector('#paymentOptionsError');if(box){box.hidden=!err;box.textContent=err?instalmentError(err):'';}const fields=err?.fields||[];for(const field of fields){const input=form.querySelector(`[data-option-field="${field}"]`);if(input){const hint=document.createElement('span');hint.className='field-error';hint.id=field.replace(/\./g,'-')+'-error';hint.role='alert';hint.textContent=instalmentError(err);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',hint.id);input.after(hint);}}}
function syncPaymentOptionFields(form){if(!form)return;for(const id of ['upfront','weekly','monthly']){const on=form.querySelector(`[name=payment_${id}]`)?.checked;form.querySelectorAll(`[data-plan-fields="${id}"] input`).forEach(input=>{input.disabled=!on;if(id==='upfront'&&input.name==='price')input.required=Boolean(on);});}}
function paymentScheduleHtml(quote){if(!quote)return '';const remaining=(quote.payments||[]).filter(p=>p.seq>1);const paidToday=`<div><dt>Amount due today</dt><dd class="money">${money(quote.today_pence)}</dd></div>`;const rest=remaining.length?`<div class="payment-dates"><dt>Remaining payments</dt><dd><ol>${remaining.map(p=>`<li><span class="payment-due">${esc(dueAt(p.due_at))}</span><span class="money">${money(p.amount_pence)}</span></li>`).join('')}</ol></dd></div>`:'<div><dt>Remaining payments</dt><dd>None. This is paid in full today.</dd></div>';const total=`<div class="total"><dt>Total after discount</dt><dd class="money">${money(quote.total_pence)}</dd></div>`;const list=quote.list_total_pence!=null&&quote.discount?`<div><dt>Before discount</dt><dd class="money">${money(quote.list_total_pence)}</dd></div><div><dt>Discount</dt><dd class="money">−${money(quote.discount.discount_pence)} (${esc(quote.discount.code)})</dd></div>`:'';return `<dl class="summary-lines payment-quote">${paidToday}${list}${total}${rest}</dl>`;}
function applyReserveQuote(quote){if(!quote)return;if($('planQuote'))$('planQuote').innerHTML=paymentScheduleHtml(quote);const btn=$('reserveSubmit');if(btn)btn.textContent=`Continue to ${modeName(config.payment_mode)} checkout · ${money(quote.today_pence)} ↗`;}
function offerOpenCheckout(err){const box=$('planPickerError');if(box){box.hidden=false;box.textContent=instalmentError(err);}if(err?.code==='PAYMENT_IN_PROGRESS'&&err.url){let actions=$('openCheckoutActions');if(!actions){actions=document.createElement('div');actions.id='openCheckoutActions';actions.className='modal-actions';(box||$('planQuote'))?.after(actions);}actions.innerHTML=`<button type="button" class="btn accent full" data-action="resume-open-checkout" data-url="${esc(err.url)}">Continue the open checkout ↗</button>`;}else{const actions=$('openCheckoutActions');if(actions)actions.remove();}}
async function refreshReserveQuote(form){const adapter=getInstalmentsApi();const selected=form?.plan?.value||'upfront';const code=form?.discount_code?.value?.trim()||null;const box=$('planPickerError');if(box){box.hidden=true;box.textContent='';}const leftover=$('openCheckoutActions');if(leftover)leftover.remove();const stillSelected=()=>(form?.plan?.value||'upfront')===selected;if(code&&adapter){const result=await adapter.quoteBooking({block_id:form.block_id.value,plan:selected,discount_code:code});if(!stillSelected())return;if(result?.quote?.plan&&result.quote.plan!==selected)return;applyReserveQuote(result.quote);return;}const plans=adapter&&pendingBlock?await adapter.getPublicPaymentOptions(pendingBlock):(window.Instalments&&pendingBlock?window.Instalments.enabledQuotesFromBlock(pendingBlock):[]);if(!stillSelected())return;applyReserveQuote(plans.find(p=>p.plan===selected)||plans[0]);}
function paymentOptionsFields(block){const I=window.Instalments;const options=I?I.optionsFromBlock(block):{upfront:{enabled:true,price_pence:block?.price_pence||9000},weekly:{enabled:false,amount_pence:0,count:8},monthly:{enabled:false,amount_pence:0,count:2}};const pounds=pence=>((Number(pence)||0)/100).toFixed(pence&&pence%100?2:0);return `<fieldset class="payment-options" id="paymentOptions"><legend>Payment options</legend><p class="form-help">Enable one or more options. For example, an eight-week block could offer £100 upfront, eight weekly payments of £12.50, or two monthly payments of £50. Changes apply to new bookings only.</p><div id="paymentOptionsError" class="error-box" role="alert" hidden></div><label class="check-label"><input name="payment_upfront" type="checkbox" ${options.upfront.enabled?'checked':''} data-action="toggle-plan"><span>Pay upfront</span></label><div class="plan-fields" data-plan-fields="upfront"><label>Upfront price (£)<input name="price" type="number" min="1" max="10000" step="0.01" value="${pounds(options.upfront.price_pence)}" ${options.upfront.enabled?'required':''} data-option-field="payment_options.upfront.price_pence"><small class="form-help">A one-off price covering the booking.</small></label></div><label class="check-label"><input name="payment_weekly" type="checkbox" ${options.weekly.enabled?'checked':''} data-action="toggle-plan"><span>Pay weekly</span></label><div class="plan-fields" data-plan-fields="weekly"><label>Weekly amount (£)<input name="payment_weekly_amount" type="number" min="0.30" max="10000" step="0.01" value="${options.weekly.amount_pence?pounds(options.weekly.amount_pence):''}" data-option-field="payment_options.weekly.amount_pence"></label><label>Number of payments<input name="payment_weekly_count" type="number" min="2" max="52" value="${options.weekly.count||8}" data-option-field="payment_options.weekly.count"><small class="form-help">2 to 52 weekly payments. The first is taken at booking.</small></label></div><label class="check-label"><input name="payment_monthly" type="checkbox" ${options.monthly.enabled?'checked':''} data-action="toggle-plan"><span>Pay monthly</span></label><div class="plan-fields" data-plan-fields="monthly"><label>Monthly amount (£)<input name="payment_monthly_amount" type="number" min="0.30" max="10000" step="0.01" value="${options.monthly.amount_pence?pounds(options.monthly.amount_pence):''}" data-option-field="payment_options.monthly.amount_pence"></label><label>Number of payments<input name="payment_monthly_count" type="number" min="2" max="12" value="${options.monthly.count||2}" data-option-field="payment_options.monthly.count"><small class="form-help">2 to 12 monthly payments. The first is taken at booking.</small></label></div></fieldset>`;}
function classPlanPrice(block){const plans=Array.isArray(block.payment_options)?block.payment_options:(window.Instalments?window.Instalments.enabledQuotesFromBlock(block):null);if(plans&&plans.length){return `<div class="price price-plans">${plans.map(p=>`<div><strong>${esc(planLabel(p.plan))}</strong> ${money(p.today_pence)}${p.plan==='upfront'?'':' due today'}<small>Total after discount ${money(p.total_pence)}</small></div>`).join('')}</div>`;}const n=block.sessions?.length||0;return `<div class="price">${money(block.price_pence)}<small>${n===1?'One session':`All ${n} sessions`} · paid upfront</small></div>`;}

