let resetToken='';
function readResetToken(loc){const query=new URLSearchParams(loc.search).get('token');if(query)return query;if(loc.pathname==='/reset-password'&&loc.hash)return loc.hash.slice(1);return '';}
function captureResetToken(){const token=readResetToken(location);if(token){resetToken=token;if(location.pathname!=='/reset-password'||location.search||location.hash)history.replaceState(null,'','/reset-password');}return resetToken;}

let me=null,csrf=null,config={},publicData=null,dashboardData=null,pendingBlock=null,routeVersion=0,authIntent=null,site=null;
async function api(path,{method='GET',body}={}){const response=await fetch(path,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw new Error('The server is unavailable. Please try again.');}if(!response.ok){const error=new Error(result.error||'Something went wrong.');error.status=response.status;if(result.code)error.code=result.code;else if(response.status===401)error.code='UNAUTHENTICATED';if(result.fields)error.fields=result.fields;if(result.url)error.url=result.url;if(result.booking_id)error.booking_id=result.booking_id;if(result.upcoming_count!=null)error.upcoming_count=result.upcoming_count;throw error;}return result;}
async function refreshMe(){const result=await api('/api/me');me=result.user;csrf=result.csrf;config=result;$('modeBar').innerHTML=`<strong>PUBLIC BOOKING SITE</strong> · ${config.payment_mode==='stripe_live'?'LIVE CARD PAYMENTS':config.payment_mode==='demo'?'SIMULATED PAYMENTS':'STRIPE SANDBOX'} · ${config.email_mode==='preview'?'EMAIL PREVIEWS':'EMAIL DELIVERY ENABLED'}`;}
