function dashboardShell(tab,content){const role=me.role;const tabs=role==='pt'?[['overview','home','Overview'],['classes','calendar','Classes & blocks'],['bookings','people','Bookings'],['instalments','wallet','Instalments'],['attendance','check','Attendance'],['messages','mail','Messages'],['payments','wallet','Payments'],['account','settings','My account']]:role==='admin'?[['overview','home','Overview'],['trainers','people','PT accounts'],['branding','settings','Branding & pages'],['bookings','people','Bookings & refunds'],['instalments','wallet','Instalments'],['stripe','wallet','Stripe setup'],['classes','calendar','Class blocks'],['messages','mail','Email previews'],['quotes','check','Motivational replies'],['account','settings','My account']]:[['bookings','calendar','My bookings'],['trainers','people','Your coach'],['account','settings','My account']];return `<div class="dashboard"><aside class="sidebar"><a class="brand" href="/" data-route><span class="brand-icon">R</span><span class="wordmark">Resilience Coaching</span></a><div class="role-label">${role==='pt'?'TRAINER WORKSPACE':role==='admin'?'PLATFORM ADMIN':'YOUR TRAINING'}</div><nav class="side-nav" aria-label="Dashboard navigation">${tabs.map(([id,ic,label])=>{const n=id==='instalments'?Number(dashboardData?.instalments?.needs_attention_count)||0:0;return `<a href="/dashboard?tab=${id}" data-route class="side-link ${tab===id?'active':''}">${icon(ic)}<span>${label}</span>${n?`<span class="nav-count" aria-label="${n} need attention">${n}</span>`:''}</a>`;}).join('')}</nav><div class="sidebar-bottom"><div class="user-name">${esc(me.name)}</div><div class="user-email">${esc(me.email)}</div><button class="text-btn" data-action="logout">Sign out</button></div></aside><main class="workspace"><header class="work-header"><div class="breadcrumb">${role==='pt'?esc(dashboardData.pt.brand_name):role==='admin'?'Your coaching platform':'Your customer account'} / ${esc(tabs.find(t=>t[0]===tab)?.[2]||tab)}</div><div class="header-actions">${role==='pt'?`<a href="/pt/${dashboardData.pt.slug}" class="btn outline small" data-route>View my site ↗</a>`:`<a href="${esc(bookingPath()||'/')}" class="btn outline small" data-route>Browse classes ↗</a>`}<button class="text-btn" data-action="logout">Sign out</button></div></header>${me.must_change_password?`<div class="info-box"><strong>Set your own password.</strong> You are using a temporary password. <button class="text-btn" data-action="password">Change it now</button>${me.role==='customer'?'':' before managing classes.'}</div>`:''}${profileMissingPrompt()}${content}</main></div>`;}
