function stats(items){return `<div class="stats">${items.map(([label,value,note])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${note||''}</small></div>`).join('')}</div>`;}
async function ptStripeView(){const setup=await api('/api/pt/stripe/setup');return heading('Your Stripe. Your class payments.','Use your own Stripe account. The website owner does not need a Stripe account.')+stats([['Net collected',money(dashboardData.stats.revenue_pence),'Current mode · after refunds · before fees'],['Refunds',money(dashboardData.stats.refunds_pence||0),'Current mode'],['Site payment mode',modeName(config.payment_mode),'Owner chooses deployment mode'],['Sandbox payment + refund',setup.sandbox_passed?'Passed':'To complete','Required before enabling live']])+`${!setup.encryption_ready||!setup.app_url_ready?'<div class="info-box">The owner must configure CREDENTIAL_ENCRYPTION_KEY and a canonical HTTPS APP_URL in Netlify before setup is complete.</div>':''}<div class="panel"><h2>Set up your account</h2><ol><li>In your own Stripe sandbox, create a restricted API key.</li><li>Save the key below. Copy your webhook URL into Stripe Workbench → Webhooks → Your account → Snapshot events.</li><li>Subscribe to the listed events, then save that endpoint’s signing secret.</li><li>Check account status, enable sandbox payments and complete a booking and full refund.</li><li>Set up live separately when ready for genuine purchases.</li></ol><p>The full class price comes from your saved booking settings. A £90 block creates one £90 charge. Stripe fees reduce your payout; Resilience Coaching adds no application fee.</p><details><summary>Permissions and payment events</summary><p>Restricted key starting permissions: ${setup.permissions.map(([n,p])=>esc(n)+' — '+esc(p)).join('; ')}. Complete sandbox checkout and refund to validate all permissions; if Stripe reports an additional required resource, grant only that permission.</p><p>Webhook events: ${setup.events.map(esc).join(', ')}. Each received event is verified with your signing secret and retrieved from your account using the restricted key. Events permission is required.</p></details></div><div class="card-grid">${['stripe_test','stripe_live'].map(mode=>{const c=setup.accounts.find(c=>c.mode===mode),live=mode==='stripe_live';return `<section class="panel"><div class="eyebrow">${live?'GENUINE CARD PAYMENTS':'NO REAL MONEY'}</div><h2>${modeName(mode)}</h2><p>${c?`Account: <strong>${esc(c.account_id)}</strong><br>${c.enabled?'New payments enabled':'New payments paused'} · ${c.charges_ready?'Card payments ready':'Card setup needed'}<br>${c.payouts_ready?'Payouts enabled':'Check payout requirements in Stripe'}<br>${c.webhook_seen_at?'Verified webhook received':'Awaiting your first verified event'}`:'No account saved for this mode.'}</p><form data-form="pt-stripe"><input type="hidden" name="mode" value="${mode}"><label>Restricted API key<input type="password" name="api_key" autocomplete="off" maxlength="256" ${c?.configured?'':'required'} placeholder="${c?.configured?'Leave blank to keep saved key':live?'rk_live_…':'rk_test_…'}"></label><label>Webhook signing secret<input type="password" name="webhook_secret" autocomplete="off" maxlength="256" placeholder="${c?.webhook_configured?'Leave blank to keep saved secret':'whsec_… — add after creating endpoint'}"></label><p class="fine">Saved secrets are never shown. Saving changes pauses new payments until you enable them again.</p><button type="submit" class="btn accent full" ${!setup.encryption_ready?'disabled':''}>Save and verify account</button></form>${c?`<label>Your webhook URL<input type="text" readonly value="${esc(c.webhook_url)}"></label><div class="list-actions"><button class="btn outline small" data-action="pt-stripe-check" data-mode="${mode}">Check account status</button><button class="btn outline small" data-action="pt-stripe-enable" data-mode="${mode}" ${!c.configured||!c.webhook_configured||!c.charges_ready||live&&!setup.sandbox_passed?'disabled':''}>${live?'Enable live payments':'Enable sandbox payments'}</button><button class="text-btn" data-action="pt-stripe-pause" data-mode="${mode}">Pause new payments</button><button class="text-btn" data-action="pt-stripe-remove" data-mode="${mode}" data-account="${esc(c.account_id)}">Remove credentials</button></div>`:''}<p class="fine">${live?'Live requires a verified sandbox booking and full refund, plus explicit confirmation. The site must also be deployed in live mode.':'A saved webhook secret is configuration only. Verify delivery with a genuine sandbox checkout before live use.'}</p></section>`;}).join('')}</div>`;}
async function stripeSetupView(){const setup=await api('/api/admin/stripe/setup');if(setup.integration==='pt_direct')return heading('PT-owned Stripe accounts.','No owner Stripe account or platform key is required. Each PT configures their own Payments page.')+`<div class="panel"><dl class="summary-lines"><div><dt>Credential encryption</dt><dd>${setup.encryption_ready?'Configured':'Needs CREDENTIAL_ENCRYPTION_KEY'}</dd></div><div><dt>Canonical HTTPS URL</dt><dd>${setup.app_url_ready?'Configured':'Needs APP_URL'}</dd></div><div><dt>Site payment mode</dt><dd>${modeName(setup.mode)}</dd></div></dl><p>Configure CREDENTIAL_ENCRYPTION_KEY in Netlify Functions as 64 random hexadecimal characters. Keep it backed up and stable. PT credentials are encrypted in the database and never returned to this dashboard. Each PT adds their own restricted key and webhook signing secret.</p><h3>Trainer connections</h3>${setup.connections.length?setup.connections.map(c=>`<p>${esc(dashboardData.pts.find(p=>p.id===c.pt_id)?.brand_name||'Trainer')} · ${modeName(c.mode)} · ${esc(c.account_id)} · ${c.enabled?'New payments enabled':'Paused / setup needed'} · ${c.webhook_seen_at?'Webhook received':'Awaiting verified webhook'}</p>`).join(''):'<p>No PTs have configured Stripe yet.</p>'}</div>`;return heading('Stripe account setup.','Each PT connects from their own Payments page. Keys are configured in Netlify, never entered here.')+`<div class="panel"><h2>${modeName(setup.mode)}</h2><dl class="summary-lines"><div><dt>Server key matches mode</dt><dd>${setup.key_ready?'Ready':'Needs configuration'}</dd></div><div><dt>Webhook secret configured</dt><dd>${setup.webhook_ready?'Yes':'No'}</dd></div><div><dt>Connect webhook secret</dt><dd>${setup.connect_webhook_ready?'Yes':'Uses main secret'}</dd></div><div><dt>HTTPS app URL</dt><dd>${setup.app_url_ready?'Ready':'Needs configuration'}</dd></div></dl><p>Set PAYMENT_MODE, STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET and APP_URL in Netlify’s Functions environment, then redeploy. For multiple trainers enable Stripe Connect and subscribe to connected-account payment events. A configured secret is not proof of webhook delivery: complete the sandbox checklist before switching live.</p><button class="btn accent" data-action="stripe-check-owner">Check server Stripe account</button><h3 style="margin-top:30px">Connected trainers</h3>${setup.connections.map(c=>`<p>${esc(c.brand_name)} · ${modeName(c.mode)} · ${esc(c.account_id)} · ${c.ready?'Ready':'Setup needed'}</p>`).join('')||'<p>No accounts connected yet.</p>'}<details><summary>Use the platform owner’s Stripe account for one trainer</summary><p>Optional for your own training business. Other PTs should use their own Connect onboarding.</p><label>Trainer<select id="stripeTrainer"><option value="">Choose trainer</option>${dashboardData.pts.map(p=>`<option value="${esc(p.id)}">${esc(p.brand_name)}</option>`).join('')}</select></label><button class="btn outline" data-action="stripe-link-owner">Link server Stripe account</button></details></div>`;}
const PROFILE_PROMPT_KEY='fit_profile_prompt_dismissed';
const PROFILE_MISSING_LABELS={business_name:'business name',contact_email:'contact email'};
function profileMissingCopy(missing){
  const items=missing.map(key=>PROFILE_MISSING_LABELS[key]||key.replace(/_/g,' '));
  if(items.length===1)return `Add your ${items[0]}; it appears on your terms, privacy and refund pages.`;
  if(items.length===2)return `Add your ${items[0]} and ${items[1]}; they appear on your terms, privacy and refund pages.`;
  const last=items.pop();
  return `Add your ${items.join(', ')} and ${last}; they appear on your terms, privacy and refund pages.`;
}
function profilePromptDismissed(missing){
  try{
    const saved=JSON.parse(localStorage.getItem(PROFILE_PROMPT_KEY)||'[]');
    return Array.isArray(saved)&&missing.every(key=>saved.includes(key));
  }catch{return false;}
}
function dismissProfilePrompt(){
  const missing=dashboardData?.pt?.profile_missing||[];
  try{localStorage.setItem(PROFILE_PROMPT_KEY,JSON.stringify([...missing].sort()));}catch{}
}
function profileMissingPrompt(){
  if(me?.role!=='pt')return '';
  const missing=dashboardData?.pt?.profile_missing;
  if(!Array.isArray(missing)||!missing.length||profilePromptDismissed(missing))return '';
  return `<div class="info-box profile-missing-prompt" role="status"><p>${esc(profileMissingCopy(missing))}</p><div class="profile-missing-actions"><a class="btn accent" href="/dashboard?tab=account" data-route>Add details</a><button type="button" class="btn outline" data-action="dismiss-profile-prompt">Dismiss</button></div></div>`;
}
function profileFieldValue(pt,key){const value=pt?.[key];return value==null?'':String(value);}
function profileForm(){
  const pt=dashboardData?.pt||{};
  const field=(name,label,attrs,help='')=>`<label class="wide-field" for="profile-${name}">${label}<input id="profile-${name}" name="${name}" ${attrs} value="${esc(profileFieldValue(pt,name))}" aria-describedby="profile-${name}-error${help?' profile-'+name+'-help':''}"><span class="field-error" id="profile-${name}-error" role="alert" aria-live="polite" hidden></span>${help?`<small class="form-help" id="profile-${name}-help">${help}</small>`:''}</label>`;
  return `<div class="panel profile-form-panel"><h2>Public profile and contact</h2><p class="muted">These details appear on your terms, privacy, refund and contact pages. Reply-to details are never shown publicly.</p><form data-form="pt-profile" class="profile-form" novalidate><div class="form-grid">${field('display_name','Trading / display name','type="text" required minlength="3" maxlength="70" autocomplete="organization"')}${field('business_name','Business name','type="text" maxlength="160" autocomplete="organization"')}<label class="wide-field" for="profile-slug">Page address<input id="profile-slug" value="/pt/${esc(pt.slug||'')}" readonly tabindex="-1" aria-readonly="true"><small class="form-help">Your public booking page. This cannot be changed here.</small></label>${field('contact_email','Contact email','type="email" maxlength="160" autocomplete="email"')}${field('contact_phone','Contact phone','type="tel" maxlength="32" autocomplete="tel"')}${field('venue_name','Venue name','type="text" maxlength="160"')}<label class="wide-field" for="profile-venue_address">Venue address<textarea id="profile-venue_address" name="venue_address" maxlength="400" rows="3" aria-describedby="profile-venue_address-error">${esc(profileFieldValue(pt,'venue_address'))}</textarea><span class="field-error" id="profile-venue_address-error" role="alert" aria-live="polite" hidden></span></label>${field('cancellation_window_hours','Cancellation window (hours)','type="number" min="0" max="720" step="1" inputmode="numeric"','Optional. A whole number from 0 to 720. Leave blank if you have not set a window.')}${field('reply_to_name','Reply-to name','type="text" maxlength="80" autocomplete="name"','Replies to booking emails go here; never shown publicly.')}${field('reply_to_email','Reply-to email','type="email" maxlength="160" autocomplete="email"','Replies to booking emails go here; never shown publicly.')}</div><div class="form-buttons"><button type="submit" class="btn accent">Save profile</button></div><p class="form-help profile-form-status" id="profileFormStatus" role="status" aria-live="polite" hidden></p></form></div>`;
}
function clearProfileErrors(form){
  form.querySelectorAll('.field-error').forEach(el=>{el.hidden=true;el.textContent='';});
  form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
  const status=$('profileFormStatus');
  if(status){status.hidden=true;status.textContent='';status.classList.remove('error');}
}
function showProfileFormError(form,error){
  const status=$('profileFormStatus');
  const fields=error?.fields&&typeof error.fields==='object'?error.fields:{};
  let focused=false;
  for(const [name,message] of Object.entries(fields)){
    const input=form.querySelector(`[name="${name}"]`);
    const box=form.querySelector(`#profile-${name}-error`);
    if(box){box.textContent=message;box.hidden=false;}
    if(input){input.setAttribute('aria-invalid','true');if(!focused){input.focus();focused=true;}}
  }
  if(status){status.textContent=error?.message||'Check the highlighted fields.';status.hidden=false;status.classList.add('error');}
}
async function savePtProfile(form,fd){
  clearProfileErrors(form);
  const status=$('profileFormStatus');
  if(status){status.textContent='Saving…';status.hidden=false;status.classList.remove('error');}
  const hoursRaw=String(fd.get('cancellation_window_hours')||'').trim();
  const body={
    display_name:String(fd.get('display_name')||'').trim(),
    business_name:String(fd.get('business_name')||'').trim(),
    contact_email:String(fd.get('contact_email')||'').trim(),
    contact_phone:String(fd.get('contact_phone')||'').trim(),
    venue_name:String(fd.get('venue_name')||'').trim(),
    venue_address:String(fd.get('venue_address')||'').trim(),
    reply_to_name:String(fd.get('reply_to_name')||'').trim(),
    reply_to_email:String(fd.get('reply_to_email')||'').trim(),
    cancellation_window_hours:hoursRaw===''?'':Number(hoursRaw)
  };
  try{
    await api('/api/pt/profile',{method:'PATCH',body});
    if(status)status.textContent='Saved.';
    toast('Profile saved.');
    await renderRoute();
  }catch(error){
    showProfileFormError(form,error);
  }
}
function accountView(){return heading('Your account.','Manage your sign-in details.')+`<div class="panel" style="max-width:570px"><dl class="summary-lines"><div><dt>Name</dt><dd>${esc(me.name)}</dd></div><div><dt>Email</dt><dd>${esc(me.email)}</dd></div><div><dt>Profile type</dt><dd>${me.role==='pt'?'Personal trainer':me.role==='admin'?'Platform admin':'Customer'}</dd></div></dl><button class="btn" data-action="password">Change password</button><p class="fine">${me.role==='admin'?`Customer and PT reset emails: ${config.password_reset_available?'configured':'not configured — see PASSWORD_RESET_SETUP.md'}.`:'If you forget your password, use the reset link on the sign-in page.'}</p></div>`+(me.role==='pt'?profileForm()+themeSettings():'');}

function bookingTable(bookings,customer=false){if(!bookings.length)return emptyState('bookings','No bookings yet. Your next session could start with one small step.');return `<div class="toolbar"><label class="sr-only" for="bookingSearch">Search bookings</label><input id="bookingSearch" type="search" placeholder="${customer?'Search class or reference':'Search customer, class or reference'}"></div><div class="table-wrap"><table><thead><tr><th>${customer?'Class':'Customer'}</th><th>${customer?'First session':'Class / reference'}</th><th>Payment</th><th>Status</th><th>Action</th></tr></thead><tbody id="bookingsBody">${bookings.map(b=>`<tr data-search="${esc((b.customer_name+' '+b.customer_email+' '+b.title+' '+b.reference).toLowerCase())}"><td><strong>${esc(customer?b.title:b.customer_name)}</strong>${customer?'':`<small>${esc(b.customer_email)}</small>`}</td><td><strong>${customer?dateText(b.sessions[0].starts_at):esc(b.title)}</strong><small>${customer?timeText(b.sessions[0].starts_at):esc(b.reference)}</small></td><td>${money(b.amount_pence)}<br><small>${modeName(b.mode)}</small></td><td>${statusPill(b.refund_status==='succeeded'?'refunded':b.status,b.mode)}${b.refunded_pence?`<small>Refunded ${money(b.refunded_pence)}</small>`:''}${['requested','pending'].includes(b.refund_status)?'<small>Refund pending</small>':''}</td><td><a href="/${b.status==='pending'?'checkout':'booking'}/${b.id}" class="btn outline small" data-route>View</a>${b.status==='pending'&&(b.mode==='demo'||(stripeMode(b.mode)&&b.mode===config.payment_mode))?` <button class="text-btn" data-action="cancel-booking" data-id="${b.id}">Cancel</button>`:''}${!customer&&stripeMode(b.mode)&&b.mode===config.payment_mode&&b.payment_intent&&['paid','review'].includes(b.status)&&b.refund_status!=='pending'?` <button class="text-btn" data-action="refund-booking" data-id="${b.id}">Refund payment</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function messageTable(rows){if(!rows.length)return '<div class="empty">No messages yet. Booking confirmations and no-show follow-ups will appear here.</div>';return `<div class="info-box">${config.email_mode==='preview'?'Messages are saved as previews. No emails are sent until a provider and verified sender are configured.':'Messages are queued for your configured email service. Check status below; failed deliveries are retried.'}</div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Subject</th><th>Type</th><th>Status</th><th>Preview</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.recipient)}</td><td><strong>${esc(m.subject)}</strong><small>${new Date(m.created_at).toLocaleString('en-GB')}</small></td><td>${m.kind==='no_show'?'No-show follow-up':'Booking confirmation'}</td><td>${statusPill(m.status)}${m.last_error?`<br><small>${esc(m.last_error)}</small>`:''}</td><td><button class="btn outline small" data-action="email-preview" data-id="${m.id}">Read message</button></td></tr>`).join('')}</tbody></table></div>`;}
function trainerCards(pts,brandingTab=false){return `<div class="trainer-grid">${pts.map(pt=>`<article class="trainer-card"><div class="swatches"><span style="background:${pt.accent}"></span><span style="background:${pt.background}"></span><span style="background:${pt.foreground}"></span></div><h3>${esc(pt.brand_name)}</h3><p>${esc(pt.owner_name)} · ${esc(pt.owner_email)}</p><div class="link">/pt/${esc(pt.slug)}</div><p style="margin:12px 0">${pt.blocks.length} classes or blocks · ${pt.published?'Page published in this preview':'Page hidden'}</p><div class="list-actions"><button class="btn small" data-action="edit-brand" data-id="${pt.id}">${brandingTab?'Customise page':'Edit branding'}</button><a class="btn outline small" href="/pt/${pt.slug}" data-route>View site ↗</a><button class="text-btn" data-action="new-block" data-pt="${pt.id}">Add class</button><button class="text-btn" data-action="delete-pt" data-id="${esc(pt.id)}" data-slug="${esc(pt.slug)}">Delete</button></div></article>`).join('')}</div>`;}
function attendanceView(data){const sessions=data.blocks.flatMap(b=>b.sessions.map(s=>({...s,title:b.title,block_id:b.id}))).sort((a,b)=>b.starts_epoch-a.starts_epoch);return heading('Every session. Every person.','Mark attendance after a session finishes. A no-show creates one supportive follow-up, with one of 20 original motivational replies.')+`<div class="toolbar"><label for="attendanceSession">Session<select id="attendanceSession"><option value="">Choose a class session</option>${sessions.map(s=>`<option value="${s.id}">${esc(s.title)} · ${dateText(s.starts_at)} ${timeText(s.starts_at)}${s.starts_epoch+s.duration_minutes*60000>Date.now()?' · upcoming':''}</option>`).join('')}</select></label></div><div id="attendanceRoster" class="empty">Choose a session to see its confirmed customers.</div>`;}
function renderRoster(sessionId){const session=dashboardData.blocks.flatMap(b=>b.sessions.map(s=>({...s,title:b.title,block_id:b.id}))).find(s=>s.id===sessionId);if(!session){$('attendanceRoster').innerHTML='Choose a session to see its confirmed customers.';return;}const bookings=dashboardData.bookings.filter(b=>b.status==='paid'&&b.block_id===session.block_id);const future=session.starts_epoch+session.duration_minutes*60000>Date.now();$('attendanceRoster').className='';$('attendanceRoster').innerHTML=`${future?'<div class="info-box">Attendance can be marked after this session finishes.</div>':''}${bookings.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Booking</th><th>Attendance</th><th>Mark attendance</th></tr></thead><tbody>${bookings.map(b=>{const status=b.sessions.find(s=>s.id===sessionId).attendance_status;return `<tr><td><strong>${esc(b.customer_name)}</strong><small>${esc(b.customer_email)}</small></td><td>${esc(b.reference)}</td><td>${statusPill(status)}</td><td><div class="attendance-actions">${[['attended','Present'],['no_show','No show'],['unmarked','Clear']].map(([value,label])=>`<button class="btn ${value==='attended'?'accent':'outline'} ${status===value?'selected':''}" data-action="attendance" data-booking="${b.id}" data-session="${session.id}" data-status="${value}" ${future?'disabled':''}>${label}</button>`).join('')}</div></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">There are no confirmed customers for this session.</div>'}`;}
async function instalmentsView(data){
  const adapter=getInstalmentsApi();
  const I=window.Instalments;
  const inst=data?.instalments||{};
  const past=Number(inst.past_due_count)||0,active=Number(inst.active_count)||0,attentionN=Number(inst.needs_attention_count)||0;
  const countLine=(past||active||attentionN)?`<p class="fine">${past||active?`Past due: ${past}. Active: ${active}.`:''}${attentionN?`${past||active?' ':''}Needs attention: ${attentionN}.`:''}</p>`:'';
  const headingHtml=heading('Instalments. Paid, upcoming and failed.','Plans for each customer and block. Stopping a plan ends future payments only. The booking and place stay, and nothing is refunded here. Use refund if you need to return a payment.')+countLine;
  const standing='<p class="fine">Past-due behaviour is configured in your own Stripe account.</p>';
  if(!adapter)return headingHtml+`<div class="error-box" role="alert">Instalment plans cannot be loaded just now.</div>`+standing;
  try{
    const result=await adapter.listInstalmentPlans({status:'all'});
    const reminder=result.past_due_reminder?.show?`<div class="info-box" role="status">${esc(result.past_due_reminder.message)}</div>`:'';
    const attentionCount=Number(result.needs_attention?.count)||0;
    const attentionMsg=I&&I.needsAttentionCopy?I.needsAttentionCopy(result.needs_attention):(result.needs_attention?.message||(attentionCount===1?'1 plan needs your attention':attentionCount+' plans need your attention'));
    const attentionBanner=attentionCount>0?`<div class="info-box attention-banner" role="status">${esc(attentionMsg)}</div>`:'';
    const list=I&&I.sortPlansForDisplay?I.sortPlansForDisplay(result.plans):[...(result.plans||[])].sort((a,b)=>Number(!!b.needs_attention)-Number(!!a.needs_attention));
    if(!list.length)return headingHtml+attentionBanner+reminder+standing+emptyState('bookings','No instalment plans yet. Upfront bookings stay on the Bookings tab.');
    return headingHtml+attentionBanner+reminder+standing+`<div class="instalment-list">${list.map(plan=>{const flagged=!!plan.needs_attention;const reason=flagged?`<p class="attention-reason">${esc((I&&I.attentionReasonLabel&&I.attentionReasonLabel(plan.attention_reason))||'Late payment, plan stopped')}</p>`:'';const hint=flagged&&plan.attention_reason==='late_payment'?`<p class="attention-hint">${esc((I&&I.LATE_PAYMENT_HINT)||'A late payment came in after this place was released. Refund the first payment or add a place for this client.')}</p>`:'';return `<article class="panel instalment-card${flagged?' needs-attention':''}"><div class="panel-head"><div><h2>${esc(plan.block_title)}</h2><p>${esc(plan.customer?.name||'')} · ${esc(plan.customer?.email||'')} · ${esc(planLabel(plan.plan))}</p></div><div class="pill-row">${flagged?'<span class="pill attention">Needs attention</span>':''}<span class="pill ${plan.status==='past_due'?'red':plan.status==='completed'?'green':plan.status==='stopped'?'grey':''}">${esc((I&&I.planStatusLabel&&I.planStatusLabel(plan.status))||plan.status)}</span></div></div>${reason}${hint}<p class="muted">Paid ${money(plan.paid_pence)} · Remaining ${money(plan.remaining_pence)} · Total after discount ${money(plan.total_pence)}</p><ol class="payment-timeline">${(plan.payments||[]).map(pay=>`<li><strong>${esc((I&&I.paymentStatusLabel&&I.paymentStatusLabel(pay.status))||pay.status)}</strong> · ${money(pay.amount_pence)}<small>${esc(dueAt(pay.due_at))}${pay.next_retry_at?' · Next retry '+dueAt(pay.next_retry_at):''}${pay.failure?' · '+esc(pay.failure):''}</small></li>`).join('')}</ol>${plan.can_stop&&me.role==='pt'&&!plan.needs_attention?`<button class="btn outline small" data-action="stop-instalment" data-id="${esc(plan.booking_id)}">Stop future payments</button>`:''}</article>`;}).join('')}</div>`;
  }catch(e){
    return headingHtml+`<div class="error-box" role="alert">${esc(instalmentError(e))}</div>`+standing;
  }
}
async function renderDashboard(version){if(!me){await renderDirectory(version);authModal('login','dashboard');return;}if(!site)await loadSite();const data=await api('/api/dashboard');if(version!==routeVersion)return;dashboardData=data;if(me.role==='admin')resetTheme();else if(me.role==='pt')theme(data.pt);else applyPageTheme();let tab=new URLSearchParams(location.search).get('tab')||(me.role==='customer'?'bookings':'overview'),content='';if(tab==='account')content=accountView();else if(me.role==='customer'){if(tab==='trainers'){navigate(bookingPath()||'/');return;}content=heading('Make room for your next step.',`Welcome back, ${esc(me.name.split(' ')[0])}. Your bookings and session dates, all in one place.`,`<a class="btn accent" href="${esc(bookingPath()||'/')}" data-route>Find a class ↗</a>`)+bookingTable(data.bookings,true);}else if(me.role==='pt'){if(tab==='overview'){const next=data.blocks.filter(b=>b.sessions[0]?.starts_epoch>Date.now()).slice(0,3);content=heading(`Keep your clients moving, ${esc(me.name.split(' ')[0])}.`,'Your classes, bookings and follow-ups. One clear view.', '<button class="btn accent" data-action="new-block">Add a class or block +</button>')+stats([['Confirmed bookings',data.stats.confirmed,'All your classes'],['Simulated revenue',money(data.stats.demo_revenue_pence),'No real money collected'],[config.payment_mode==='stripe_live'?'Live Stripe net':'Stripe sandbox net',money(data.stats.revenue_pence),'After refunds · before Stripe fees'],['No-shows',data.stats.no_shows,'Marked attendance']])+`<div class="panel"><div class="panel-head"><div><h2>Your next class blocks</h2><p>Places are shared across customer accounts.</p></div><a class="text-btn" href="/dashboard?tab=classes" data-route>See all classes</a></div><div class="panel-list">${next.length?next.map(b=>`<div class="list-row"><div><strong>${esc(b.title)}</strong><p>${dateText(b.sessions[0].starts_at)} · ${b.sessions.length} sessions · ${b.available} places available</p></div><button class="btn outline small" data-action="edit-block" data-id="${b.id}">Manage</button></div>`).join(''):'<p class="muted">Add your first future class to get started.</p>'}</div></div><div class="info-box">Your own client page: <a href="/pt/${data.pt.slug}" data-route><strong>/pt/${data.pt.slug} ↗</strong></a><br>Share your named page with clients. The platform admin can customise its colours, text and training highlights.</div>`;}else if(tab==='classes')content=heading('Build a schedule that fits.','One-off classes, four-week blocks, six-week programmes or your own format. Set every session date yourself.','<button class="btn accent" data-action="new-block">Add class or block +</button>')+`<div class="card-grid">${data.blocks.map((b,i)=>classCard(b,i,{manage:true})).join('')}</div>`;else if(tab==='bookings')content=heading('Your bookings. Clear and current.','Confirmed places and active checkouts, with customer contact details.')+bookingTable(data.bookings);else if(tab==='instalments')content=await instalmentsView(data);else if(tab==='attendance')content=attendanceView(data);else if(tab==='messages')content=heading('A little encouragement goes a long way.','View booking confirmations and supportive no-show messages.')+messageTable(data.outbox);else if(tab==='payments'){if(config.stripe_integration==='pt_direct')content=await ptStripeView();else{const stripe=data.pt.stripe||{},state=stripe.state||(data.pt.stripe_ready?'active':data.pt.stripe_connected?'onboarding_incomplete':'not_connected'),copy=connectStateCopy[state]||connectStateCopy.not_connected;content=heading('Your Stripe. Your class payments.','Link your account securely with Stripe, then charge the upfront price you set for each class or block.')+stats([['Net collected',money(data.stats.revenue_pence),'Current mode · after refunds · before fees'],['Refunds',money(data.stats.refunds_pence||0),'Current payment mode'],['Confirmed bookings',data.stats.confirmed,'All payment modes'],['Payment mode',modeName(config.payment_mode),config.payment_mode==='stripe_live'?'Real card payments':'Test payments only']])+`<div class="panel" data-connect-state="${esc(state)}"><h2 style="font-size:25px">Connect your Stripe account</h2><p><span class="pill ${copy.pill}">${esc(copy.label)}</span></p>${stripe.account_id||data.pt.stripe_account_id?`<p>Connected account: <strong>${esc(stripe.account_id||data.pt.stripe_account_id)}</strong></p>`:''}<p class="muted">${copy.body}</p>${connectRequirements(stripe.requirements)}<ol><li>Connect Stripe and complete your business and bank information.</li><li>Check account status until card payments are enabled.</li><li>Add a class and set its total upfront price.</li><li>Share your page. Customers pay that exact price in Stripe Checkout.</li></ol><p>Example: a block priced at £90 creates a £90 charge for all its sessions. Stripe fees are deducted from your payout; there is no added booking fee.</p><div class="list-actions"><button class="btn accent" data-action="stripe-connect">${state==='not_connected'?'Connect my Stripe account':'Continue Stripe setup'} ↗</button>${state!=='not_connected'?'<button class="btn outline" data-action="stripe-status">Check account status</button>':''}</div><p class="fine">Current mode: ${modeName(config.payment_mode)}. ${config.payment_mode==='stripe_live'?'Customers make genuine purchases with real cards.':'Use Stripe sandbox details and test cards only.'} The platform owner configures Stripe Connect. Test and live accounts are separate.</p></div>`;}}}else{if(tab==='overview')content=heading('Your coaching platform, connected.','Give each trainer their own branded site, classes and client experience.','<button class="btn accent" data-action="new-pt">Create a PT account +</button>')+stats([['PT accounts',data.stats.pts,'Individually branded pages'],['Customer accounts',data.stats.customers,'Shared sign-in across trainers'],['Confirmed bookings',data.stats.confirmed,'All payment modes'],['Reply library',20,'Random no-show encouragement']])+trainerCards(data.pts);else if(['trainers','branding'].includes(tab))content=heading(tab==='branding'?'Their coaching. Their own look.':'Give every PT their own space.',tab==='branding'?'Customise each page name, address, colour palette, copy and training highlights.':'Create PT accounts with a unique named home page.','<button class="btn accent" data-action="new-pt">Create PT account +</button>')+trainerCards(data.pts,tab==='branding');else if(tab==='stripe')content=await stripeSetupView();else if(tab==='bookings')content=heading('Bookings and refunds.','Only verified Stripe payment notifications confirm bookings. Refunds return to the original payment method.')+bookingTable(data.bookings);else if(tab==='instalments')content=await instalmentsView(data);else if(tab==='classes')content=heading('Every trainer. Every block.','Manage custom programme lengths and individual class dates.','<button class="btn accent" data-action="new-block">Add a class or block +</button>')+`<div class="card-grid">${data.pts.flatMap(pt=>pt.blocks.map((b,i)=>classCard({...b,title:pt.brand_name+' / '+b.title},i,{manage:true}))).join('')}</div>`;else if(tab==='messages')content=heading('Platform email previews.','No-show follow-ups and confirmations, with delivery status.')+messageTable(data.outbox);else if(tab==='quotes')content=heading('Twenty ways to encourage a return.','Each no-show follow-up chooses one original message at random. Repeat attendance edits do not send duplicate follow-ups.')+`<div class="quote-grid">${data.quotes.map((q,i)=>`<div class="quote-card"><small>REPLY ${String(i+1).padStart(2,'0')}</small>${esc(q)}</div>`).join('')}</div>`;}
if(!content){navigate('/dashboard');return;}$('app').innerHTML=dashboardShell(tab,content);document.title=(me.role==='admin'?'Platform admin':me.role==='pt'?'Trainer workspace':'My bookings')+' — Resilience Coaching';setPageMeta({title:document.title,path:'/dashboard'});}
async function renderRoute(){const version=++routeVersion;try{setPageMeta({path:location.pathname||'/'});captureResetToken();if(location.pathname==='/reset-password'){await refreshMe();if(!site)await loadSite();applyPageTheme();$('app').innerHTML=resetPasswordView();document.title='Choose a new password — Resilience Coaching';return;}await refreshMe();const path=location.pathname;if(path==='/forgot-password'){if(!site)await loadSite();applyPageTheme();$('app').innerHTML=forgotPasswordView();document.title='Reset your password — Resilience Coaching';return;}if(path==='/dashboard')return await renderDashboard(version);const check=path.match(/^\/(checkout|booking)\/([^/]+)$/);if(check)return await renderCheckout(check[2],version,check[1]==='booking');await loadSite();if(version!==routeVersion)return;if(path==='/trainers'){if(isMultiPt())return await renderDirectory(version);const dest=bookingPath()||'/';if(dest!=='/trainers'){history.replaceState(null,'',dest);return renderRoute();}return await renderLanding(version);}if(path==='/login'||path==='/signup'){if(isMultiPt())await renderDirectory(version);else await renderLanding(version);authModal(path.slice(1),'dashboard');return;}if(path==='/terms'||path==='/privacy'||path==='/refunds'||path==='/contact'){applyPageTheme();$('app').innerHTML=legalPage(path);return;}const match=path.match(/^\/pt\/([a-z0-9-]+)$/);if(match)return await renderHome(match[1],version);if(path==='/')return await renderLanding(version);const dest=bookingPath()||'/';$('app').innerHTML=`<div class="container">${brandHeader()}<div class="loading"><h2>This page is not available.</h2><a class="btn" href="${esc(dest)}" data-route>Find your coach</a></div></div>`;}catch(e){if(location.pathname==='/'||location.pathname==='/trainers'){try{if(!site)await loadSite();}catch(err){}return renderLanding(version,'error');}const dest=bookingPath()||'/';$('app').innerHTML=`<div class="container">${brandHeader()}<div class="loading"><h2>${e.status===404?'This training page is not available.':'We could not load your training space.'}</h2><p>${esc(e.message)}</p><a href="${esc(dest)}" class="btn" data-route>Find your coach</a></div></div>`;}}
function nextMonday(){const day=new Date();day.setUTCDate(day.getUTCDate()+((8-day.getUTCDay())%7||7));return day.toISOString().slice(0,10)+'T18:30';}
function allBlocks(){return me.role==='pt'?dashboardData.blocks:dashboardData.pts.flatMap(p=>p.blocks);}
function blockForm(block=null,ptId=null){const first=block?.sessions[0]?.starts_at||nextMonday(),n=block?.sessions.length||6;const ptOptions=me.role==='admin'?`<label class="wide-field">Trainer<select name="pt_id" ${block?'disabled':''}>${dashboardData.pts.map(p=>`<option value="${p.id}" ${(ptId||block?.pt_id)===p.id?'selected':''}>${esc(p.brand_name)}</option>`).join('')}</select></label>`:'';modal(block?'Make this class your own.':'Build a class that fits.',`<p>Choose any programme length. Use one session for a single class, or add dates for a block. Dates are locked once bookings exist.</p><form data-form="block"><input type="hidden" name="id" value="${block?.id||''}">${block?'':`<input type="hidden" name="create_key" value="${uid()}">`}<div class="form-grid">${ptOptions}<label class="wide-field">Class or block name<input name="title" value="${esc(block?.title||'')}" required minlength="3" maxlength="100" placeholder="e.g. Eight-week strength club"></label><label class="wide-field">What customers can expect<textarea name="description" required minlength="5" maxlength="1000">${esc(block?.description||'Coached strength and conditioning, with support to help you progress at your own pace.')}</textarea></label><label class="wide-field">Venue<input name="venue" value="${esc(block?.venue||'')}" required minlength="3" maxlength="160" placeholder="Studio name and address"></label>${paymentOptionsFields(block)}<label>Maximum participants<input name="capacity" type="number" min="1" max="100" value="${block?.capacity||15}" required><small class="form-help">Choose 1–100 participants. Confirmed bookings and active checkouts count toward this limit.</small></label></div><div class="session-generator"><label>First date & time<input id="firstSession" type="datetime-local" value="${first}" required></label><label>Number of weeks / sessions<input id="sessionCount" type="number" min="1" max="52" value="${n}" required></label><label>Minutes<input id="sessionMinutes" type="number" min="15" max="240" step="5" value="${block?.sessions[0]?.duration_minutes||60}" required></label></div><button type="button" class="btn outline small" data-action="generate-dates">Generate weekly dates</button><p class="fine">All times are Europe/London. Edit each date below if your schedule varies. Blocks are not restricted to six weeks.</p><div id="sessionEditor" class="session-editor"></div><label class="check-label"><input name="published" type="checkbox" ${!block||block.published?'checked':''}><span>Show this class on the customer's booking page.</span></label>${block?`<label class="check-label"><input name="closed" type="checkbox" ${block.closed?'checked':''}><span>Close new bookings. Existing confirmed bookings and attendance stay available.</span></label>`:''}<button type="submit" class="btn accent full">${block?'Save class changes':'Create class or block'} ↗</button></form>`,{wide:true,eyebrow:'YOUR CLASSES / CUSTOM SCHEDULE'});renderSessionEditor(block?.sessions||weeklyDates(first,n,60));syncPaymentOptionFields(document.querySelector('form[data-form=block]'));}
function weeklyDates(first,count,minutes){if(!first||count<1||count>52)throw new Error('Choose a first date and 1–52 sessions.');const date=first.slice(0,10),time=first.slice(11);return Array.from({length:count},(_,i)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i*7);return {starts_at:d.toISOString().slice(0,10)+'T'+time,duration_minutes:minutes};});}
function renderSessionEditor(sessions){$('sessionEditor').innerHTML=sessions.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><label class="sr-only" for="sessionDate${i}">Session ${i+1} date and time</label><input id="sessionDate${i}" name="session_date" aria-label="Session ${i+1} date and time" type="datetime-local" value="${s.starts_at}" required><label class="duration-label">Minutes<input name="session_minutes" aria-label="Session ${i+1} duration in minutes" type="number" min="15" max="240" value="${s.duration_minutes}" required></label></div>`).join('');}
function brandForm(pt=null){const d=pt||{brand_name:'YOUR TRAINING CLUB',slug:'your-training-club',tagline:'Train with purpose. Grow in confidence.',description:'Coached training, a supportive group and a regular routine to help you make progress at your own pace.',about:'Build strength, practise better technique and improve your fitness with personal coaching and a small group to support you.',accent:'#ffd43b',background:'#ffffff',foreground:'#111111',features:['Strength & conditioning','Small groups. Personal coaching.','Progress at your own pace'],published:true};modal(pt?'Their coaching. Their own look.':'Create a trainer’s own space.',`<p>${pt?'Change the branding, text and named page for this PT. Changing the page address means old links will no longer work.':'The PT gets a separate account and their own named client page. You control the starting brand and content.'}</p><form data-form="brand"><input type="hidden" name="id" value="${pt?.id||''}">${pt?'':`<input type="hidden" name="create_key" value="${uid()}">`}<div class="form-grid">${!pt?'<label>PT’s name<input name="owner_name" required minlength="2" maxlength="80" placeholder="e.g. Alex Morgan"></label><label>PT’s email<input name="email" type="email" required placeholder="coach@example.com"></label>':''}<label>Site name<input name="brand_name" value="${esc(d.brand_name)}" required minlength="3" maxlength="70"></label><label>Named page address<input name="slug" value="${esc(d.slug)}" required pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="50"><small class="form-help">Your app address /pt/<span id="slugPreview">${esc(d.slug)}</span></small></label><label class="wide-field">Home page headline<input name="tagline" value="${esc(d.tagline)}" required minlength="5" maxlength="120"></label><label class="wide-field">Home page introduction<textarea name="description" required minlength="10" maxlength="700">${esc(d.description)}</textarea></label><label class="wide-field">Training and improvement information<textarea name="about" required minlength="10" maxlength="1200">${esc(d.about)}</textarea></label><label class="wide-field">Training highlights (one per line, maximum 3)<textarea name="features" required>${esc(d.features.join('\n'))}</textarea></label><div class="triple"><label>Highlight colour<input type="color" name="accent" value="${d.accent}"></label><label>Page background<input type="color" name="background" value="${d.background}"></label><label>Text colour<input type="color" name="foreground" value="${d.foreground}"></label></div></div><div class="demo-choices"><button type="button" class="btn outline small" data-action="theme-preset" data-theme="yellow">Black / white / yellow</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="coral">Warm studio</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="blue">Blue & white</button><button type="button" class="btn outline small" data-action="theme-preset" data-theme="dark">Dark training club</button></div><div class="brand-preview" id="brandPreview"><strong></strong><p></p></div><label class="check-label"><input name="published" type="checkbox" ${d.published?'checked':''}><span>Make this trainer page available on the public site.</span></label><button type="submit" class="btn accent full">${pt?'Save trainer branding':'Create PT account & page'} ↗</button></form>`,{wide:true,eyebrow:'PLATFORM ADMIN / PT BRANDING'});updateBrandPreview();}
function updateBrandPreview(){const form=$('modalBody').querySelector('form[data-form=brand]');if(!form)return;const preview=$('brandPreview');preview.style.background=form.elements.background.value;preview.style.color=form.elements.foreground.value;preview.style.borderColor=form.elements.accent.value;preview.querySelector('strong').textContent=form.elements.brand_name.value;preview.querySelector('p').textContent=form.elements.tagline.value;$('slugPreview').textContent=form.elements.slug.value;}
function passwordForm(){modal('Make your account your own.',`<p>Changing your password signs out your other sessions.</p><form data-form="password"><div class="form-grid"><label class="wide-field">Current password<input name="current_password" type="password" required autocomplete="current-password"></label><label class="wide-field">New password<input name="new_password" type="password" minlength="12" maxlength="200" required autocomplete="new-password"><small class="form-help">At least 12 characters.</small></label></div><button class="btn accent full" type="submit">Save my new password ↗</button></form>`);}
function showEmail(row){modal(row.subject,`<p>To: ${esc(row.recipient)}<br>Status: ${row.status==='preview'?'Preview only — no email was sent':esc(row.status)}</p><div class="email-body">${esc(row.body)}</div>`,{eyebrow:'CUSTOMER FOLLOW-UP'});}
let pendingAttendance=null,pendingCancel=null;
document.addEventListener('click',async event=>{const link=event.target.closest('a[data-route]');if(link){event.preventDefault();navigate(link.getAttribute('href'));return;}const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;try{if(action==='forgot-password'){if($('modal').open)$('modal').close();navigate('/forgot-password');}else if(action==='close-modal')$('modal').close();else if(action==='retry-site')renderRoute();else if(action==='dismiss-profile-prompt'){dismissProfilePrompt();const box=el.closest('.profile-missing-prompt');if(box)box.remove();}else if(action==='login'||action==='signup')authModal(action);else if(action==='logout'){await api('/api/auth/logout',{method:'POST',body:{}});me=null;csrf=null;authIntent=null;pendingBlock=null;navigate('/');toast('You are signed out.');}else if(action==='book')await bookingModal(publicData.blocks.find(b=>b.id===el.dataset.id));else if(action==='pay-demo'){el.disabled=true;const data=await api('/api/bookings/'+el.dataset.id+'/pay',{method:'POST',body:{result:el.dataset.result}});navigate('/booking/'+data.booking.id);toast(data.booking.status==='paid'?'Your test booking is confirmed.':'Test payment declined. The place has been released.');}else if(action==='resume-stripe'){el.disabled=true;const result=await api('/api/bookings/'+el.dataset.id+'/checkout',{method:'POST',body:{}});location.assign(result.url);}else if(action==='refund-booking'){const id=el.dataset.id;const b=dashboardData?.bookings?.find(b=>b.id===id);modal('Refund this payment?',`<p>Refund ${b?money(b.amount_pence-b.refunded_pence):'the remaining balance'} to the original card? ${config.payment_mode==='stripe_live'?'This returns real money.':'This is a sandbox refund; no real money moves.'} A full successful refund cancels the booking and releases its place.</p><button class="btn accent full" data-action="confirm-refund" data-id="${id}" data-token="${uid()}">Confirm refund</button>`);}else if(action==='confirm-refund'){el.disabled=true;const result=await api('/api/bookings/'+el.dataset.id+'/refund',{method:'POST',body:{request_token:el.dataset.token}});$('modal').close();await renderRoute();toast(result.refund_status==='succeeded'?'Payment refunded.':'Refund submitted. Its status will update after Stripe responds.');}else if(action==='cancel-booking'){pendingCancel=el.dataset.id;modal('Cancel this booking?',`<p>For a Stripe checkout, the place is released only after Stripe confirms it is no longer payable. Completed payments must be refunded by the trainer.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Keep booking</button><button class="btn danger" data-action="confirm-cancel">Cancel booking</button></div>`);}else if(action==='confirm-cancel'){await api('/api/bookings/'+pendingCancel+'/cancel',{method:'POST',body:{}});$('modal').close();await renderRoute();toast('Booking cancelled. The place is available again.');}else if(action==='refresh-route')await renderRoute();else if(action==='new-block')blockForm(null,el.dataset.pt||null);else if(action==='edit-block')blockForm(allBlocks().find(b=>b.id===el.dataset.id));else if(action==='generate-dates')renderSessionEditor(weeklyDates($('firstSession').value,Number($('sessionCount').value),Number($('sessionMinutes').value)));else if(action==='toggle-plan')syncPaymentOptionFields(el.closest('form'));else if(action==='select-plan'){const form=el.closest('form');try{await refreshReserveQuote(form);}catch(e){offerOpenCheckout(e);}}else if(action==='apply-discount'){const form=el.closest('form');el.disabled=true;try{await refreshReserveQuote(form);}catch(e){offerOpenCheckout(e);}finally{el.disabled=false;}}else if(action==='resume-open-checkout'){const url=el.dataset.url;if(!url)return;$('modal').close();if(followCheckoutUrl(url)==='in-app')navigate(url);else location.assign(url);}else if(action==='stop-instalment'){modal('Stop future payments?',`<p>This cancels remaining instalments. The booking and place stay, and nothing is refunded. To return a payment, use refund instead.</p><div class="modal-actions"><button class="btn outline" data-action="close-modal">Keep plan</button><button class="btn danger" data-action="confirm-stop-instalment" data-id="${esc(el.dataset.id)}" data-token="${uid()}">Stop future payments</button></div>`,{eyebrow:'TRAINER ONLY'});}else if(action==='confirm-stop-instalment'){if(me.role!=='pt'){modalError(instalmentError({code:'FORBIDDEN'}));}else{el.disabled=true;try{const result=await getInstalmentsApi().stopInstalmentPlan(el.dataset.id,{request_token:el.dataset.token});$('modal').close();await renderRoute();toast(result.status==='stopped'?(result.voided_payments?`Future payments stopped. ${result.voided_payments} unpaid instalments were cancelled.`:'Future payments stopped.'):'Plan updated.');}catch(e){modalError(instalmentError(e));el.disabled=false;}}}else if(action==='new-pt')brandForm();else if(action==='edit-brand')brandForm(dashboardData.pts.find(p=>p.id===el.dataset.id));else if(action==='delete-pt')deletePtConfirm(el.dataset.id,el.dataset.slug);else if(action==='delete-pt-go'){el.disabled=true;try{await deletePtGo(el.dataset.id,el.dataset.slug,false);}finally{el.disabled=false;}}else if(action==='delete-pt-force'){el.disabled=true;try{await deletePtGo(el.dataset.id,el.dataset.slug,true);}finally{el.disabled=false;}}else if(action==='theme-preset'){const presets={yellow:['#ffd43b','#ffffff','#111111'],coral:['#fb9374','#faf6f2','#272727'],blue:['#438bff','#ffffff','#101c34'],dark:['#ffd43b','#111111','#ffffff']};const [accent,bg,fg]=presets[el.dataset.theme],form=$('modalBody').querySelector('form');form.elements.accent.value=accent;form.elements.background.value=bg;form.elements.foreground.value=fg;updateBrandPreview();}else if(action==='password')passwordForm();else if(action==='email-preview')showEmail(dashboardData.outbox.find(r=>r.id===el.dataset.id));else if(action==='attendance'){pendingAttendance={booking_id:el.dataset.booking,session_id:el.dataset.session,status:el.dataset.status};if(el.dataset.status==='no_show'){const booking=dashboardData.bookings.find(b=>b.id===el.dataset.booking);modal('Send a little encouragement.',`<p>Mark ${esc(booking.customer_name)} as a no-show for this session?</p><div class="info-box"><strong>Sorry we missed you at class!</strong><br>To: ${esc(booking.customer_email)}<br>One motivational reply is selected at random from the 20-message library. ${config.email_mode==='preview'?'The email will be saved as a preview; it will not be sent.':'The email will be queued for your configured delivery service.'}<br>Repeated marking does not create another email.</div><div class="modal-actions"><button class="btn outline" data-action="close-modal">Keep attendance</button><button class="btn accent" data-action="confirm-attendance">Mark no show</button></div>`);}else await markAttendance();}else if(action==='confirm-attendance')await markAttendance();else if(action==='pt-stripe-check'){await api('/api/pt/stripe/check',{method:'POST',body:{mode:el.dataset.mode}});await renderRoute();toast('Stripe account status checked. Validate checkout and refund permissions in sandbox.');}else if(action==='pt-stripe-enable'){const mode=el.dataset.mode;modal(mode==='stripe_live'?'Enable genuine payments?':'Enable sandbox payments?',`<p>${mode==='stripe_live'?'Customers will be charged real money when the site is in live mode. Confirm you have completed sandbox tests and are ready to sell genuine services.':'Enable test payments for your saved sandbox account. Complete a booking and full refund to verify the integration.'}</p><button class="btn accent full" data-action="pt-stripe-enable-confirm" data-mode="${mode}">Confirm ${mode==='stripe_live'?'live':'sandbox'} enablement</button>`);}else if(action==='pt-stripe-enable-confirm'){await api('/api/pt/stripe/enable',{method:'POST',body:{mode:el.dataset.mode,live_ack:el.dataset.mode==='stripe_live'}});$('modal').close();await renderRoute();toast('Payments enabled for this account and mode.');}else if(action==='pt-stripe-pause'){await api('/api/pt/stripe/disconnect',{method:'POST',body:{mode:el.dataset.mode}});await renderRoute();toast('New payments paused. Existing checkout, refund and webhook processing remain available.');}else if(action==='pt-stripe-remove'){modal('Remove saved Stripe credentials?',`<p>This stops automated payment updates and refunds for this account. Historical bookings remain. Manage remaining payments directly in Stripe, or reconnect the same account later. Active checkouts must be cancelled or expire first. Revoke the key and delete the webhook in Stripe separately.</p><form data-form="pt-stripe-remove"><input type="hidden" name="mode" value="${el.dataset.mode}"><label>Type ${esc(el.dataset.account)} to confirm<input name="confirm_account" required autocomplete="off"></label><button class="btn danger full" type="submit">Remove credentials</button></form>`);}else if(action==='stripe-check-owner'){const r=await api('/api/admin/stripe/check',{method:'POST',body:{}});modal('Your Stripe account',`<dl class="summary-lines"><div><dt>Account</dt><dd>${esc(r.id)}</dd></div><div><dt>Business</dt><dd>${esc(r.name||'Not provided')}</dd></div><div><dt>Email</dt><dd>${esc(r.email||'Not provided')}</dd></div><div><dt>Card payments</dt><dd>${r.charges_enabled?'Enabled':'Setup required'}</dd></div><div><dt>Mode</dt><dd>${modeName(r.mode)}</dd></div></dl>`);}else if(action==='stripe-link-owner'){const pt=$('stripeTrainer').value;if(!pt)throw new Error('Choose a trainer first.');modal('Link the owner’s Stripe account?',`<p>This trainer will receive payments in the Stripe account configured by the server key. Other trainers should connect their own accounts from Payments.</p><button class="btn accent full" data-action="stripe-link-confirm" data-pt="${esc(pt)}">Link this account</button>`);}else if(action==='stripe-link-confirm'){await api('/api/admin/stripe/link',{method:'POST',body:{pt_id:el.dataset.pt}});$('modal').close();await renderRoute();toast('Stripe account linked. Check its status before taking payments.');}else if(action==='stripe-connect'){el.disabled=true;try{const result=await api('/api/pt/stripe/connect',{method:'POST',body:{}});location.assign(result.url);}finally{el.disabled=false;}}else if(action==='stripe-status'){const result=await api('/api/pt/stripe/status',{method:'POST',body:{}});await renderRoute();toast((connectStateCopy[result.state]||connectStateCopy.onboarding_incomplete).toast);}}catch(e){el.disabled=false;if(promptSignIn(e)){}else if($('modal').open)modalError(instalmentError(e));else toast(instalmentError(e));}});
async function markAttendance(){const selected={...pendingAttendance},result=await api('/api/attendance',{method:'POST',body:selected});if($('modal').open)$('modal').close();dashboardData=await api('/api/dashboard');renderRoster(selected.session_id);if(result.email){showEmail({...result.email,recipient:dashboardData.bookings.find(b=>b.id===selected.booking_id).customer_email});}else toast(selected.status==='attended'?'Attendance marked as present.':'Attendance cleared.');}
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const kind=form.dataset.form,fd=new FormData(form),fields=Object.fromEntries(fd.entries()),button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{if(kind==='pt-stripe'){await api('/api/pt/stripe/credentials',{method:'POST',body:fields});form.reset();await renderRoute();toast('Account verified and credentials saved. Configure the webhook, then enable payments.');}else if(kind==='pt-stripe-remove'){await api('/api/pt/stripe/disconnect',{method:'POST',body:{...fields,erase:true}});$('modal').close();await renderRoute();toast('Saved credentials removed. Historical bookings remain.');}else if(kind==='forgot-password'){const result=await api('/api/auth/forgot-password',{method:'POST',body:{email:fields.email}});$('resetFeedback').textContent=result.message;}else if(kind==='reset-password'){if(fields.new_password!==fields.confirm_password)throw new Error('Your passwords do not match.');await api('/api/auth/reset-password',{method:'POST',body:{token:resetToken,new_password:fields.new_password}});resetToken='';me=null;csrf=null;navigate('/login');toast('Password reset. Sign in with your new password.');}else if(kind==='login'||kind==='signup'){const result=await api('/api/auth/'+kind,{method:'POST',body:{...fields,demo_acknowledged:fd.has('demo_acknowledged')}});me=result.user;csrf=result.csrf;$('modal').close();if(authIntent==='book'&&pendingBlock){const block=pendingBlock;authIntent=null;await renderRoute();await bookingModal(block);}else{const destination=authIntent==='return'&&authReturnPath?authReturnPath:'/dashboard';authIntent=null;authReturnPath=null;navigate(destination);toast('You are signed in.');}}else if(kind==='reserve'){const adapter=getInstalmentsApi();const body={block_id:fields.block_id,checkout_token:fields.checkout_token,plan:fields.plan||'upfront',discount_code:fields.discount_code?.trim()||null};let result;try{result=adapter?await adapter.createBooking(body):await api('/api/bookings',{method:'POST',body:body});}catch(e){offerOpenCheckout(e);throw e;}if(!result)return;$('modal').close();const url=result.url;if(!url)throw new Error(instalmentError({code:'NOT_FOUND'}));if(followCheckoutUrl(url)==='in-app')navigate(url);else location.assign(url);}else if(kind==='password'){const result=await api('/api/auth/password',{method:'POST',body:fields});csrf=result.csrf;$('modal').close();await renderRoute();toast('Your password has been updated.');}else if(kind==='block'){const dates=Array.from(form.querySelectorAll('[name=session_date]')).map(x=>x.value),minutes=Array.from(form.querySelectorAll('[name=session_minutes]')).map(x=>Number(x.value));const I=window.Instalments;const payment_options=I?I.parsePaymentOptionsFromForm(fd):null;if(payment_options){const check=I.validatePaymentOptions(payment_options,{lastSessionAt:dates.at(-1)});if(!check.ok){const err={code:check.code,fields:check.fields};showPaymentOptionErrors(form,err);throw err;}}const payload={title:fields.title,description:fields.description,venue:fields.venue,capacity:Number(fields.capacity),published:fd.has('published'),closed:fd.has('closed'),sessions:dates.map((starts_at,i)=>({starts_at,duration_minutes:minutes[i]}))};if(fields.create_key)payload.create_key=fields.create_key;if(fields.pt_id)payload.pt_id=fields.pt_id;if(payment_options){payload.payment_options=payment_options;if(payment_options.upfront?.enabled)payload.price_pence=payment_options.upfront.price_pence;}else payload.price_pence=Math.round(Number(fields.price)*100);try{const adapter=getInstalmentsApi();if(adapter&&payment_options)await adapter.saveBlockPaymentOptions(fields.id||null,payment_options,{lastSessionAt:dates.at(-1),body:payload});else await api(fields.id?'/api/blocks/'+fields.id:'/api/blocks',{method:fields.id?'PUT':'POST',body:payload});}catch(e){if(e.code&&form.querySelector('#paymentOptions')){showPaymentOptionErrors(form,e);throw e;}throw e;}$('modal').close();await renderRoute();toast(fields.id?'Class changes saved.':'Your class is ready to book.');}else if(kind==='brand'){const payload={...fields,published:fd.has('published'),features:fields.features.split('\n').map(s=>s.trim()).filter(Boolean)};const result=await api(fields.id?'/api/admin/pts/'+fields.id:'/api/admin/pts',{method:fields.id?'PUT':'POST',body:payload});$('modal').close();await renderRoute();if(!fields.id)modal('Their training space is ready.',`<p>The PT account and named page have been created. Save these temporary sign-in details and share them privately with the PT.</p><div class="credential"><strong>${esc(result.email)}</strong><br>Temporary password:<br><code>${esc(result.temporary_password)}</code></div><div class="info-box">This password is shown only now. The PT must change it before managing classes. No invitation email was sent.</div><a class="btn accent full" href="${result.path}" data-route>View their new home page ↗</a>`);else toast('Trainer branding saved.');}else if(kind==='pt-profile'){await savePtProfile(form,fd);}else if(kind==='pt-theme'){await saveTheme(form);}}catch(e){if(promptSignIn(e)){/* sign-in */ }else if(kind==='pt-profile'||(kind==='block'&&e.code&&$('paymentOptions'))){/* field errors already shown */}else if($('resetFeedback'))$('resetFeedback').textContent=e.message;else if(kind==='reserve'&&$('planPickerError')){$('planPickerError').hidden=false;$('planPickerError').textContent=instalmentError(e);}else if($('modal').open)modalError(instalmentError(e));else toast(instalmentError(e));}finally{if(button)button.disabled=false;}});

function deletePtConfirm(id,slug,{upcomingCount=null}={}){const force=upcomingCount!=null;const copy=force?`<p>This trainer has ${Number(upcomingCount)} upcoming paid or reserved booking${Number(upcomingCount)===1?'':'s'}. Deleting unpublishes their classes and revokes their sign-in. Booking and payment history is kept so refunds still work.</p>`:'<p>This removes their public page and sign-in. Classes are unpublished. Booking and payment history is kept so refunds still work.</p>';modal(force?'Delete this trainer anyway?':'Delete this trainer?',`${copy}<p>Type <strong>${esc(slug)}</strong> to confirm.</p><label>Page address<input id="deletePtSlug" autocomplete="off" spellcheck="false"></label><button class="btn danger full" data-action="${force?'delete-pt-force':'delete-pt-go'}" data-id="${esc(id)}" data-slug="${esc(slug)}">${force?'Delete anyway':'Delete trainer'}</button>`);}
async function deletePtGo(id,slug,force=false){const typed=($('deletePtSlug')?.value||'').trim();if(typed!==slug){modalError('Type the page address exactly to confirm.');return;}try{await api('/api/admin/pts/'+encodeURIComponent(id)+(force?'?force=1':''),{method:'DELETE'});$('modal').close();await renderRoute();toast('Trainer deleted.');}catch(e){if(e.status===409&&e.upcoming_count!=null){deletePtConfirm(id,slug,{upcomingCount:e.upcoming_count});return;}modalError(e.message);}}
document.addEventListener('input',event=>{if(event.target.id==='bookingSearch'){const q=event.target.value.toLowerCase();document.querySelectorAll('#bookingsBody tr').forEach(row=>row.hidden=!row.dataset.search.includes(q));}if(event.target.closest('form[data-form=brand]'))updateBrandPreview();});
document.addEventListener('change',event=>{if(event.target.id==='attendanceSession')renderRoster(event.target.value);if(event.target.id==='themePreset')updateThemePreview();});
captureResetToken();window.addEventListener('popstate',renderRoute);renderRoute();
